-- 019_yemen_codab_complete.sql
-- CANONICAL DATASET: Yemen Central Statistical Organization (CSO),
-- via OCHA COD-AB "Yemen - Subnational Administrative Boundaries" v01
-- (22 governorates, 335 districts; reviewed 2024-12-23; AR+EN; CC BY-IGO).
-- HDX: https://data.humdata.org/dataset/cod-ab-yem
-- Local 018 rows preserved (IDs, custom codes, standard Arabic names kept;
-- dataset AR transliteration variants NOT forced over them).
-- 7 documented naming-variant aliases (local name -> COD-AB pcode):
--   AMN/مدينة عمران->YE2915, DLA/مدينة الضالع->YE3006, JWF/برط->YE1610,
--   MHR/الغيضة->YE2804, SAD/صعدة المدينة->YE2215, SNA/سنحان->YE2305,
--   SQT/قلنسية->YE3202.
-- New districts reuse pcode as stable code. Idempotent.
BEGIN;

-- ---------- additive columns ----------
ALTER TABLE locations_governorates ADD COLUMN IF NOT EXISTS pcode TEXT;
ALTER TABLE locations_governorates ADD COLUMN IF NOT EXISTS name_en TEXT;
ALTER TABLE locations_districts ADD COLUMN IF NOT EXISTS pcode TEXT;
ALTER TABLE locations_districts ADD COLUMN IF NOT EXISTS name_en TEXT;
ALTER TABLE locations_neighborhoods ADD COLUMN IF NOT EXISTS name_en TEXT;
ALTER TABLE locations_countries ADD COLUMN IF NOT EXISTS calling_code TEXT;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'locations_governorates_pcode_key') THEN
    ALTER TABLE locations_governorates ADD CONSTRAINT locations_governorates_pcode_key UNIQUE (pcode);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'locations_districts_pcode_key') THEN
    ALTER TABLE locations_districts ADD CONSTRAINT locations_districts_pcode_key UNIQUE (pcode);
  END IF;
END $$;

